// This file is generated by AI.

// 配音队列调度规则测试。
//
// 这些规则是功能的正确性核心: 一旦"严格串行 / 立即优先 / 按角色分组"被破坏,
// 服务端的全局参考音频缓存就会被并发请求污染, 且模型会被反复重载。

import { describe, expect, it } from 'vitest';

import { executionOrder, groupByCharacter, nextTask, summarize, type QueueTask } from '../src/voice/queue';

function task(
  id: string,
  kind: 'test' | 'generate',
  characterId: string | null,
  status: QueueTask['status'] = 'pending'
): QueueTask {
  return { id, kind, characterId, status };
}

describe('groupByCharacter', () => {
  it('把同角色的任务聚成一组, 并保持首次出现顺序', () => {
    const groups = groupByCharacter([
      task('1', 'generate', 'anon'),
      task('2', 'generate', 'soyo'),
      task('3', 'generate', 'anon'),
      task('4', 'generate', 'soyo'),
    ]);
    expect(groups.map((group) => group.characterId)).toEqual(['anon', 'soyo']);
    expect(groups[0].tasks.map((item) => item.id)).toEqual(['1', '3']);
    expect(groups[1].tasks.map((item) => item.id)).toEqual(['2', '4']);
  });

  it('未指定角色的任务归入同一组', () => {
    const groups = groupByCharacter([task('1', 'test', null), task('2', 'test', null)]);
    expect(groups).toHaveLength(1);
    expect(groups[0].characterId).toBeNull();
    expect(groups[0].tasks.map((item) => item.id)).toEqual(['1', '2']);
  });

  it('不同角色不会互相穿插', () => {
    const groups = groupByCharacter([
      task('a', 'generate', 'x'),
      task('b', 'generate', 'y'),
      task('c', 'generate', 'x'),
      task('d', 'generate', 'y'),
      task('e', 'generate', 'z'),
    ]);
    for (const group of groups) {
      const characterIds = new Set(group.tasks.map((item) => item.characterId));
      expect(characterIds.size).toBe(1);
    }
  });
});

describe('executionOrder', () => {
  it('立即队列 (测试) 整体优先于普通队列 (生成)', () => {
    const order = executionOrder([
      task('gen1', 'generate', 'anon'),
      task('test1', 'test', 'soyo'),
      task('gen2', 'generate', 'anon'),
    ]);
    expect(order.map((item) => item.id)).toEqual(['test1', 'gen1', 'gen2']);
  });

  it('立即队列内部同样按角色分组', () => {
    const order = executionOrder([task('t1', 'test', 'anon'), task('t2', 'test', 'soyo'), task('t3', 'test', 'anon')]);
    expect(order.map((item) => item.id)).toEqual(['t1', 't3', 't2']);
  });

  it('不会把同角色的任务跨队列归并 (否则立即任务会被拖住)', () => {
    const order = executionOrder([task('gen-anon', 'generate', 'anon'), task('test-anon', 'test', 'anon')]);
    // 测试即使与生成任务同角色, 也必须排在前面
    expect(order[0].id).toBe('test-anon');
  });

  it('已完成 / 失败 / 取消的任务不参与调度', () => {
    const order = executionOrder([
      task('done', 'test', 'anon', 'done'),
      task('failed', 'test', 'anon', 'failed'),
      task('canceled', 'test', 'anon', 'canceled'),
      task('running', 'test', 'anon', 'running'),
      task('pending', 'generate', 'anon', 'pending'),
    ]);
    expect(order.map((item) => item.id)).toEqual(['pending']);
  });

  it('空队列返回空顺序', () => {
    expect(executionOrder([])).toEqual([]);
  });
});

describe('nextTask', () => {
  it('串行取队首: 立即队列优先', () => {
    const tasks = [task('gen', 'generate', 'anon'), task('test', 'test', 'soyo')];
    expect(nextTask(tasks)?.id).toBe('test');
  });

  it('队列为空时返回 null', () => {
    expect(nextTask([])).toBeNull();
  });
});

describe('summarize', () => {
  const estimate = (tasks: QueueTask[]) => tasks.length * 1000;

  it('统计各队列待处理数', () => {
    const summary = summarize(
      [
        task('1', 'test', 'a'),
        task('2', 'test', 'b'),
        task('3', 'generate', 'a'),
        task('4', 'generate', 'a', 'running'),
        task('5', 'test', 'a', 'done'),
      ],
      estimate
    );
    expect(summary.pending).toBe(3);
    expect(summary.pendingTest).toBe(2);
    expect(summary.pendingGenerate).toBe(1);
    expect(summary.running).toBe(1);
  });

  it('立即队列对生成任务的延后量包含运行中任务', () => {
    const summary = summarize(
      [task('1', 'test', 'a'), task('2', 'test', 'b'), task('3', 'generate', 'a', 'running')],
      estimate
    );
    // 1 个运行中 + 2 个立即 = 3 秒
    expect(summary.delayMillis).toBe(3000);
  });

  it('空队列的统计为零', () => {
    const summary = summarize([], estimate);
    expect(summary).toEqual({
      pending: 0,
      pendingTest: 0,
      pendingGenerate: 0,
      running: 0,
      delayMillis: 0,
    });
  });
});
